// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max / 2);
        vm.deal(actor, amount);
        uint256 preTxOriginBalance = c.getBalance(tx.origin);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        uint256 postTxOriginBalance = c.getBalance(tx.origin);
        assertTrue(preTxOriginBalance == postTxOriginBalance);
    }
}
